CREATE TABLE `retry_jobs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Internal auto-increment primary key; referenced by pipeline_runs.active_retry_job_id',
  `run_id` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL COMMENT 'UUID of the pipeline run this job retries (pipeline_runs.run_id; logical reference, no foreign key)',
  `job_type` varchar(32) NOT NULL COMMENT 'Stage to retry: NODE_RED_FETCH (CPE status fetch) or KAFKA_PUBLISH (publish the evaluated payload)',
  `ticket_id` bigint(20) unsigned NOT NULL COMMENT 'Related RT ticket ID (same as pipeline_runs.ticket_id)',
  `cpe_id` varchar(12) DEFAULT NULL COMMENT 'CPE the retry is for',
  `request_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Everything the retry needs without in-memory context: the original RT request (NODE_RED_FETCH) or the evaluated payload (KAFKA_PUBLISH)' CHECK (json_valid(`request_payload`)),
  `last_error` text DEFAULT NULL COMMENT 'Error of the most recent failed attempt; cleared when the job is resolved',
  `attempt_count` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'Scheduled retry attempts made so far; never exceeds max_attempts',
  `max_attempts` tinyint(3) unsigned NOT NULL COMMENT 'Attempts allowed before FAILED_PERMANENT: the number of entries in RETRY_WORKER_BACKOFF_SCHEDULE (default 3)',
  `status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING (waiting for next_retry_at), RETRYING (claimed by a worker), RESOLVED (retry succeeded), FAILED_PERMANENT (attempts exhausted)',
  `next_retry_at` datetime(3) NOT NULL COMMENT 'Earliest time a worker may claim the job, from the backoff schedule',
  `locked_by` varchar(100) DEFAULT NULL COMMENT 'Worker holding the job as <hostname>-<pid>; NULL when not claimed',
  `locked_at` datetime(3) DEFAULT NULL COMMENT 'When locked_by claimed the job; a lock older than RETRY_WORKER_LOCK_TTL_MS (default 5m) can be reclaimed',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) COMMENT 'Job creation timestamp',
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3) COMMENT 'Last update timestamp',
  `resolved_at` datetime(3) DEFAULT NULL COMMENT 'When the job reached RESOLVED; NULL otherwise',
  PRIMARY KEY (`id`),
  KEY `idx_retry_jobs_run_id` (`run_id`),
  KEY `idx_retry_jobs_claim` (`status`,`next_retry_at`),
  CONSTRAINT `chk_retry_jobs_status` CHECK (`status` in ('PENDING','RETRYING','RESOLVED','FAILED_PERMANENT')),
  CONSTRAINT `chk_retry_jobs_attempts` CHECK (`attempt_count` <= `max_attempts`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Failed pipeline stages waiting to be retried by the Retry Worker'